const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const pick = (l, value) => value[l];

export const auditGuideSlugs = new Set(priorityGuides.map(guide => 'guides/' + guide.slug));
export const auditCategorySlugs = new Set(guideCategories.map(category => 'guides/rubrique/' + category.slug));
export const auditTouchedSlugs = new Set([
  ...auditGuideSlugs,
  ...auditCategorySlugs,
  'faq', 'offres', 'about', 'modify-company', 'domiciliation', 'tarif/domiciliation', 'legal', 'privacy', 'cookies'
]);

export const isAuditGuide = slug => auditGuideSlugs.has(slug);

export function entriesForCategory(categorySlug) {
  const fresh = priorityGuides.filter(guide => guide.category === categorySlug).map(guide => ({slug:guide.slug, title:guide.title, fresh:true}));
  const known = cataloguedGuides.filter(guide => guide.category === categorySlug);
  return [...fresh, ...known];
}

export function renderGuideArticle(language, guide) {
  const sections = guide.sections.map(([heading, paragraph], index) => `<h2 id="etape-${index + 1}">${esc(pick(language, heading))}</h2><p>${esc(pick(language, paragraph))}</p>`).join('');
  const faqs = guide.faqs.map(([question, answer]) => `<details class="seo-faq"><summary>${esc(pick(language, question))}</summary><p>${esc(pick(language, answer))}</p></details>`).join('');
  const links = guide.links.map(item => `<li><a href="/${language}/${item.path}/">${esc(pick(language, item.label))}</a></li>`).join('');
  const sources = guide.sources.map(item => `<li><a href="${esc(item.href)}">${esc(pick(language, item.label))}</a></li>`).join('');
  const updated = {fr:`Mis à jour le 18 novembre 2026`, en:'Updated 18 November 2026', ar:'حُدّث في 18 نوفمبر 2026'}[language];
  const caution = {
    fr:'Ce guide est informatif. Il ne remplace pas l’examen de votre dossier. Les exigences des administrations, des banques et des autres organismes peuvent évoluer.',
    en:'This guide is general information. It does not replace a review of your file. Requirements of administrations, banks and other bodies can change.',
    ar:'هذا الدليل معلومات عامة. ولا يعوّض دراسة ملفكم. وقد تتغير متطلبات الإدارات والبنوك والهيئات الأخرى.'
  }[language];
  const questionTitle = {fr:'Questions pratiques', en:'Practical questions', ar:'أسئلة عملية'}[language];
  const linkTitle = {fr:'Pages liées', en:'Related pages', ar:'صفحات ذات صلة'}[language];
  const sourceTitle = {fr:'Sources', en:'Sources', ar:'المصادر'}[language];
  return `<article class="article seo-guide"><p class="seo-revised"><time datetime="${auditDate}">${updated}</time></p>${sections}<h2 id="questions">${questionTitle}</h2>${faqs}<h2 id="liens">${linkTitle}</h2><ul>${links}</ul><h2 id="sources">${sourceTitle}</h2><p>${esc(caution)}</p><ul>${sources}</ul></article>`;
}

export function renderCategoryBody(language, category) {
  const items = entriesForCategory(category.slug).map(entry => `<li><a href="/${language}/guides/${entry.slug}/">${esc(pick(language, entry.title))}</a></li>`).join('');
  const intro = {
    fr:'Ces pages existent dans le dépôt. Elles ne résument pas l’ensemble des guides éventuellement publiés par ailleurs.',
    en:'These pages exist in the repository. They do not summarise every guide that may be published elsewhere.',
    ar:'هذه الصفحات موجودة في المستودع. وهي لا تلخص كل دليل قد يُنشر في مكان آخر.'
  }[language];
  const serviceLinks = {
    creation:`<a href="/${language}/creation-entreprise/">${pick(language, text('Accompagnement à la création','Formation support','مواكبة التأسيس'))}</a>`,
    domiciliation:`<a href="/${language}/domiciliation/">${pick(language, text('Page domiciliation','Domiciliation page','صفحة التوطين'))}</a>`,
    mre:`<a href="/${language}/investir-au-maroc/">${pick(language, text('Investir au Maroc','Invest in Morocco','الاستثمار بالمغرب'))}</a>`,
    modification:`<a href="/${language}/modify-company/">${pick(language, text('Modifier ma société','Change my company','تعديل شركتي'))}</a>`,
    fiscalite:`<a href="/${language}/conseil-fiscal/">${pick(language, text('Conseil fiscal','Tax advisory','الاستشارة الضريبية'))}</a>`
  }[category.slug];
  return `<article class="article"><p>${esc(intro)}</p><ul class="guide-hub-list">${items}</ul><p>${serviceLinks} · <a href="/${language}/guides/">${pick(language, text('Tous les guides','All guides','كل الأدلة'))}</a></p></article>`;
}

export function renderHub(language) {
  const nav = guideCategories.map(category => `<a href="/${language}/guides/rubrique/${category.slug}/">${esc(pick(language, category.title))}</a>`).join('');
  const cards = priorityGuides.map(guide => `<li><a href="/${language}/guides/${guide.slug}/"><strong>${esc(pick(language, guide.title))}</strong></a><p>${esc(pick(language, guide.description))}</p></li>`).join('');
  const heading = {fr:'Rubriques', en:'Topics', ar:'المحاور'}[language];
  const essential = {fr:'Guides essentiels', en:'Essential guides', ar:'أدلة أساسية'}[language];
  const note = {
    fr:'Cinq rubriques pour trouver une création, une domiciliation, un projet depuis l’étranger, une modification ou un repère fiscal. Les autres guides restent listés ensuite.',
    en:'Five topics for formation, domiciliation, a project from abroad, a company change or a tax note. The other guides remain listed below.',
    ar:'خمسة محاور للتأسيس والتوطين والمشروع من الخارج وتعديل الشركة أو معطى ضريبي. وتبقى الأدلة الأخرى معروضة بعده.'
  }[language];
  return `<div class="seo-content guide-hub"><h2>${heading}</h2><p>${esc(note)}</p><nav class="guide-hub-nav" aria-label="${heading}">${nav}</nav><h2>${essential}</h2><ul class="guide-hub-list">${cards}</ul></div>`;
}

export function renderRelated(language, slugs) {
  const guides = slugs.map(slug => priorityGuides.find(guide => guide.slug === slug)).filter(Boolean);
  const items = guides.map(guide => `<li><a href="/${language}/guides/${guide.slug}/">${esc(pick(language, guide.title))}</a></li>`).join('');
  const heading = {fr:'Guides liés', en:'Related guides', ar:'أدلة ذات صلة'}[language];
  return `<div class="seo-content"><section id="guides-lies"><h2>${heading}</h2><ul>${items}</ul></section></div>`;
}
